// Resource barrier helper
static D3D12_RESOURCE_BARRIER make_transition(
    ID3D12Resource* res, D3D12_RESOURCE_STATES before, D3D12_RESOURCE_STATES after)
{
    D3D12_RESOURCE_BARRIER b = {};
    b.Type = D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;
    b.Transition.pResource = res;
    b.Transition.Subresource = D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES;
    b.Transition.StateBefore = before;
    b.Transition.StateAfter = after;
    return b;
}

// Encoder1 conv weights for cbPass_Weights (b1), one 256-dword array per preset,
// plus encoder1_weights_by_preset[]. Generated from your FSR4 source by
// scripts/embed_initializer.py (AMD-derived data, not committed).
#include "fsr4_encoder1_weights.h"

// Scratch buffer sizes from AMD's shader_selector.cpp
static const size_t SCRATCH_SIZE_1080P = 20880256;
static const size_t SCRATCH_SIZE_2160P = 83232256;
static const size_t SCRATCH_SIZE_4320P = 332352256;

static size_t get_scratch_size(uint32_t upscale_w, uint32_t upscale_h) {
    if (upscale_w > 3840 || upscale_h > 2160) return SCRATCH_SIZE_4320P;
    if (upscale_w > 1920 || upscale_h > 1080) return SCRATCH_SIZE_2160P;
    return SCRATCH_SIZE_1080P;
}

// RCAS constants computation — matches AMD's FsrRcasCon in ffx_fsr1.h
// Input: sharpness in "stops" (0.0 = max sharpening, higher = less sharpening)
// AMD's provider remaps desc->sharpness [0,1] to stops [2,0] before calling this.
static void compute_rcas_config(uint32_t config[4], float sharpness_stops) {
    // Transform from stops to linear value (matches AMD's exp2(-sharpness))
    float sharpness_linear = exp2f(-sharpness_stops);

    // config[0] = float sharpness as uint32 bits (FsrRcasF reads this with ffxAsFloat)
    memcpy(&config[0], &sharpness_linear, sizeof(uint32_t));

    // config[1] = packed half2(sharpness, sharpness) for the half-float path
    // Pack two float16 values into a uint32
    uint16_t h = 0;
    // Simple float-to-half conversion for the sharpness value
    {
        uint32_t f;
        memcpy(&f, &sharpness_linear, sizeof(uint32_t));
        uint32_t sign = (f >> 16) & 0x8000;
        int32_t exp = ((f >> 23) & 0xFF) - 127 + 15;
        uint32_t mantissa = (f >> 13) & 0x3FF;
        if (exp <= 0) { h = (uint16_t)sign; }
        else if (exp >= 31) { h = (uint16_t)(sign | 0x7C00); }
        else { h = (uint16_t)(sign | (exp << 10) | mantissa); }
    }
    config[1] = ((uint32_t)h << 16) | (uint32_t)h;

    config[2] = 0;
    config[3] = 0;
}

#ifdef FSR4_RELEASE
void FSR4D3D12Pipeline::logf(const char*, ...) {}
#else
void FSR4D3D12Pipeline::logf(const char* fmt, ...) {
    if (!log) return;
    va_list args;
    va_start(args, fmt);
    vfprintf(log, fmt, args);
    va_end(args);
    fflush(log);
}
#endif

// =========================================================================
// Helper: create a committed D3D12 resource
// =========================================================================

static ID3D12Resource* create_texture_2d(
    ID3D12Device* device, uint32_t w, uint32_t h,
    DXGI_FORMAT format, D3D12_RESOURCE_FLAGS flags,
    D3D12_RESOURCE_STATES initial_state,
    const D3D12_CLEAR_VALUE* clear_value = nullptr)
{
    D3D12_HEAP_PROPERTIES heap = {};
    heap.Type = D3D12_HEAP_TYPE_DEFAULT;

    D3D12_RESOURCE_DESC desc = {};
    desc.Dimension = D3D12_RESOURCE_DIMENSION_TEXTURE2D;
    desc.Width = w;
    desc.Height = h;
    desc.DepthOrArraySize = 1;
    desc.MipLevels = 1;
    desc.Format = format;
    desc.SampleDesc.Count = 1;
    desc.Layout = D3D12_TEXTURE_LAYOUT_UNKNOWN;
    desc.Flags = flags;

    ID3D12Resource* res = nullptr;
    HRESULT hr = device->CreateCommittedResource(
        &heap, D3D12_HEAP_FLAG_NONE, &desc, initial_state,
        clear_value, IID_PPV_ARGS(&res));
    if (FAILED(hr)) return nullptr;
    return res;
}

static ID3D12Resource* create_buffer(
    ID3D12Device* device, size_t size,
    D3D12_HEAP_TYPE heap_type, D3D12_RESOURCE_FLAGS flags,
    D3D12_RESOURCE_STATES initial_state)
{
    D3D12_HEAP_PROPERTIES heap = {};
    heap.Type = heap_type;

    D3D12_RESOURCE_DESC desc = {};
    desc.Dimension = D3D12_RESOURCE_DIMENSION_BUFFER;
    desc.Width = size;
    desc.Height = 1;
    desc.DepthOrArraySize = 1;
    desc.MipLevels = 1;
    desc.Format = DXGI_FORMAT_UNKNOWN;
    desc.SampleDesc.Count = 1;
    desc.Layout = D3D12_TEXTURE_LAYOUT_ROW_MAJOR;
    desc.Flags = flags;

    ID3D12Resource* res = nullptr;
    HRESULT hr = device->CreateCommittedResource(
        &heap, D3D12_HEAP_FLAG_NONE, &desc, initial_state,
        nullptr, IID_PPV_ARGS(&res));
    if (FAILED(hr)) return nullptr;
    return res;
}

// =========================================================================
// Root Signature Creation
// =========================================================================

bool FSR4D3D12Pipeline::create_root_signatures(ID3D12Device* device) {
    HRESULT hr;

    // --- Pre/Post/RCAS Root Signature ---
    // b0: OptimizedConstants (pre/post) or RcasConstants (rcas) — root CBV
    // b1: cbPass_Weights (encoder1 conv weights, 256 uint32_t) — root CBV
    // t0-t20: SRV descriptor table (21 entries)
    // u0-u12: UAV descriptor table (13 entries)
    // s0: static sampler (linear clamp)
    {
        D3D12_ROOT_PARAMETER params[PP_ROOT_PARAM_COUNT] = {};

        // [0] Root CBV at b0
        params[PP_ROOT_CBV_B0].ParameterType = D3D12_ROOT_PARAMETER_TYPE_CBV;
        params[PP_ROOT_CBV_B0].Descriptor.ShaderRegister = 0;
        params[PP_ROOT_CBV_B0].Descriptor.RegisterSpace = 0;
        params[PP_ROOT_CBV_B0].ShaderVisibility = D3D12_SHADER_VISIBILITY_ALL;

        // [1] Root CBV at b1 (cbPass_Weights for pre-shader encoder1 conv)
        params[PP_ROOT_CBV_B1].ParameterType = D3D12_ROOT_PARAMETER_TYPE_CBV;
        params[PP_ROOT_CBV_B1].Descriptor.ShaderRegister = 1;
        params[PP_ROOT_CBV_B1].Descriptor.RegisterSpace = 0;
        params[PP_ROOT_CBV_B1].ShaderVisibility = D3D12_SHADER_VISIBILITY_ALL;

        // [2] SRV descriptor table: t0-t20
        D3D12_DESCRIPTOR_RANGE srv_range = {};
        srv_range.RangeType = D3D12_DESCRIPTOR_RANGE_TYPE_SRV;
        srv_range.NumDescriptors = DESC_SRV_COUNT;
        srv_range.BaseShaderRegister = 0;
        srv_range.RegisterSpace = 0;
        srv_range.OffsetInDescriptorsFromTableStart = 0;

        params[PP_SRV_TABLE].ParameterType = D3D12_ROOT_PARAMETER_TYPE_DESCRIPTOR_TABLE;
        params[PP_SRV_TABLE].DescriptorTable.NumDescriptorRanges = 1;
        params[PP_SRV_TABLE].DescriptorTable.pDescriptorRanges = &srv_range;
        params[PP_SRV_TABLE].ShaderVisibility = D3D12_SHADER_VISIBILITY_ALL;

        // [3] UAV descriptor table: u0-u12
        D3D12_DESCRIPTOR_RANGE uav_range = {};
        uav_range.RangeType = D3D12_DESCRIPTOR_RANGE_TYPE_UAV;
        uav_range.NumDescriptors = DESC_UAV_COUNT;
        uav_range.BaseShaderRegister = 0;
        uav_range.RegisterSpace = 0;
        uav_range.OffsetInDescriptorsFromTableStart = 0;

        params[PP_UAV_TABLE].ParameterType = D3D12_ROOT_PARAMETER_TYPE_DESCRIPTOR_TABLE;
        params[PP_UAV_TABLE].DescriptorTable.NumDescriptorRanges = 1;
        params[PP_UAV_TABLE].DescriptorTable.pDescriptorRanges = &uav_range;
        params[PP_UAV_TABLE].ShaderVisibility = D3D12_SHADER_VISIBILITY_ALL;

        // Static sampler at s0: linear clamp
        D3D12_STATIC_SAMPLER_DESC sampler = {};
        sampler.Filter = D3D12_FILTER_MIN_MAG_MIP_LINEAR;
        sampler.AddressU = D3D12_TEXTURE_ADDRESS_MODE_CLAMP;
        sampler.AddressV = D3D12_TEXTURE_ADDRESS_MODE_CLAMP;
        sampler.AddressW = D3D12_TEXTURE_ADDRESS_MODE_CLAMP;
        sampler.ShaderRegister = 0;
        sampler.RegisterSpace = 0;
        sampler.ShaderVisibility = D3D12_SHADER_VISIBILITY_ALL;

        D3D12_ROOT_SIGNATURE_DESC desc = {};
        desc.NumParameters = PP_ROOT_PARAM_COUNT;
        desc.pParameters = params;
        desc.NumStaticSamplers = 1;
        desc.pStaticSamplers = &sampler;
        desc.Flags = D3D12_ROOT_SIGNATURE_FLAG_NONE;

        ID3DBlob* sig_blob = nullptr;
        ID3DBlob* error_blob = nullptr;
        hr = D3D12SerializeRootSignature(&desc, D3D_ROOT_SIGNATURE_VERSION_1,
                                          &sig_blob, &error_blob);
        if (FAILED(hr)) {
            logf("ERROR: Pre/Post root sig serialization failed: 0x%x\n", hr);
            if (error_blob) {
                logf("  %s\n", (char*)error_blob->GetBufferPointer());
                error_blob->Release();
            }
            return false;
        }

        hr = device->CreateRootSignature(0, sig_blob->GetBufferPointer(),
                                          sig_blob->GetBufferSize(),
                                          IID_PPV_ARGS(&pre_post_root_sig));
        sig_blob->Release();
        if (error_blob) error_blob->Release();
        if (FAILED(hr)) {
            logf("ERROR: Pre/Post root sig creation failed: 0x%x\n", hr);
            return false;
        }
    }

    // --- Model Root Signature ---
    // t0: Root SRV (scratch buffer read region)
    // t1: Root SRV (initializer buffer)
    // u0: Root UAV (scratch buffer write region)
    // u1: Root UAV (scratch buffer)
    {
        D3D12_ROOT_PARAMETER params[MODEL_ROOT_PARAM_COUNT] = {};

        // [0] Root SRV at t0
        params[MODEL_ROOT_SRV_T0].ParameterType = D3D12_ROOT_PARAMETER_TYPE_SRV;
        params[MODEL_ROOT_SRV_T0].Descriptor.ShaderRegister = 0;
        params[MODEL_ROOT_SRV_T0].Descriptor.RegisterSpace = 0;
        params[MODEL_ROOT_SRV_T0].ShaderVisibility = D3D12_SHADER_VISIBILITY_ALL;

        // [1] Root SRV at t1
        params[MODEL_ROOT_SRV_T1].ParameterType = D3D12_ROOT_PARAMETER_TYPE_SRV;
        params[MODEL_ROOT_SRV_T1].Descriptor.ShaderRegister = 1;
        params[MODEL_ROOT_SRV_T1].Descriptor.RegisterSpace = 0;
        params[MODEL_ROOT_SRV_T1].ShaderVisibility = D3D12_SHADER_VISIBILITY_ALL;

        // [2] Root UAV at u0
        params[MODEL_ROOT_UAV_U0].ParameterType = D3D12_ROOT_PARAMETER_TYPE_UAV;
        params[MODEL_ROOT_UAV_U0].Descriptor.ShaderRegister = 0;
        params[MODEL_ROOT_UAV_U0].Descriptor.RegisterSpace = 0;
        params[MODEL_ROOT_UAV_U0].ShaderVisibility = D3D12_SHADER_VISIBILITY_ALL;

        // [3] Root UAV at u1
        params[MODEL_ROOT_UAV_U1].ParameterType = D3D12_ROOT_PARAMETER_TYPE_UAV;
        params[MODEL_ROOT_UAV_U1].Descriptor.ShaderRegister = 1;
        params[MODEL_ROOT_UAV_U1].Descriptor.RegisterSpace = 0;
        params[MODEL_ROOT_UAV_U1].ShaderVisibility = D3D12_SHADER_VISIBILITY_ALL;

        D3D12_ROOT_SIGNATURE_DESC desc = {};
        desc.NumParameters = MODEL_ROOT_PARAM_COUNT;
        desc.pParameters = params;
        desc.Flags = D3D12_ROOT_SIGNATURE_FLAG_NONE;

        ID3DBlob* sig_blob = nullptr;
        ID3DBlob* error_blob = nullptr;
        hr = D3D12SerializeRootSignature(&desc, D3D_ROOT_SIGNATURE_VERSION_1,
                                          &sig_blob, &error_blob);
        if (FAILED(hr)) {
            logf("ERROR: Model root sig serialization failed: 0x%x\n", hr);
            if (error_blob) {
                logf("  %s\n", (char*)error_blob->GetBufferPointer());
                error_blob->Release();
            }
            return false;
        }

        hr = device->CreateRootSignature(0, sig_blob->GetBufferPointer(),
                                          sig_blob->GetBufferSize(),
                                          IID_PPV_ARGS(&model_root_sig));
        sig_blob->Release();
        if (error_blob) error_blob->Release();
        if (FAILED(hr)) {
            logf("ERROR: Model root sig creation failed: 0x%x\n", hr);
            return false;
        }
    }

    logf("Root signatures created (pre/post + model)\n");
    return true;
}

// =========================================================================
// PSO Creation
// =========================================================================

bool FSR4D3D12Pipeline::create_psos(ID3D12Device* device) {
    // Select shader tier based on quality preset and resolution
    const char* tier_names[] = { "1080p", "2160p", "4320p" };
    const char* preset_names[] = { "quality", "balanced", "performance", "ultraperf" };
    const ShaderBlob* tier = g_fsr4_presets[quality_preset][resolution_tier];

    logf("Creating PSOs for %s/%s (preset=%d, tier=%d)\n",
         preset_names[quality_preset], tier_names[resolution_tier],
         quality_preset, resolution_tier);

    // Map PSO index to shader blob and root signature
    // Tier layout: [0]=pre, [1-12]=pass1-12, [13]=post
    struct PSOInfo {
        const uint8_t* bytecode;
        size_t size;
        ID3D12RootSignature* root_sig;
        const char* name;
    };

    PSOInfo pso_infos[PSO_COUNT] = {
        { tier[0].data,  tier[0].size,  pre_post_root_sig, "Pre"     },
        { tier[1].data,  tier[1].size,  model_root_sig,    "Pass1"   },
        { tier[2].data,  tier[2].size,  model_root_sig,    "Pass2"   },
        { tier[3].data,  tier[3].size,  model_root_sig,    "Pass3"   },
        { tier[4].data,  tier[4].size,  model_root_sig,    "Pass4"   },
        { tier[5].data,  tier[5].size,  model_root_sig,    "Pass5"   },
        { tier[6].data,  tier[6].size,  model_root_sig,    "Pass6"   },
        { tier[7].data,  tier[7].size,  model_root_sig,    "Pass7"   },
        { tier[8].data,  tier[8].size,  model_root_sig,    "Pass8"   },
        { tier[9].data,  tier[9].size,  model_root_sig,    "Pass9"   },
        { tier[10].data, tier[10].size, model_root_sig,    "Pass10"  },
        { tier[11].data, tier[11].size, model_root_sig,    "Pass11"  },
        { tier[12].data, tier[12].size, model_root_sig,    "Pass12"  },
        { tier[13].data, tier[13].size, pre_post_root_sig, "Post"    },
        { g_fsr4_rcas.data, g_fsr4_rcas.size, pre_post_root_sig, "RCAS" },
        { g_fsr4_post_debug[quality_preset][resolution_tier].data,
          g_fsr4_post_debug[quality_preset][resolution_tier].size,
          pre_post_root_sig, "PostDebug" },
        { g_fsr4_debug_overlay.data, g_fsr4_debug_overlay.size,
          pre_post_root_sig, "DebugOverlay" },
    };

    for (int i = 0; i < PSO_COUNT; i++) {
        D3D12_COMPUTE_PIPELINE_STATE_DESC desc = {};
        desc.pRootSignature = pso_infos[i].root_sig;
        desc.CS.pShaderBytecode = pso_infos[i].bytecode;
        desc.CS.BytecodeLength = pso_infos[i].size;

        HRESULT hr = device->CreateComputePipelineState(&desc, IID_PPV_ARGS(&pso[i]));
        if (FAILED(hr)) {
            logf("ERROR: PSO creation failed for %s: 0x%x\n", pso_infos[i].name, hr);
            return false;
        }
    }

    // Create alternate Post PSO (AMD original, no fast_exp) for A/B comparison
    {
        const ShaderBlob& post_normal = g_fsr4_post_normal[quality_preset][resolution_tier];
        D3D12_COMPUTE_PIPELINE_STATE_DESC desc = {};
        desc.pRootSignature = pre_post_root_sig;
        desc.CS.pShaderBytecode = post_normal.data;
        desc.CS.BytecodeLength = post_normal.size;

        HRESULT hr = device->CreateComputePipelineState(&desc, IID_PPV_ARGS(&pso_post_normal));
        if (FAILED(hr)) {
            logf("ERROR: PSO creation failed for PostNormal: 0x%x\n", hr);
            return false;
        }
    }

    logf("Created %d PSOs + PostNormal (%s/%s)\n", PSO_COUNT,
         preset_names[quality_preset], tier_names[resolution_tier]);
    return true;
}

// =========================================================================
// Internal Resource Creation
// =========================================================================

bool FSR4D3D12Pipeline::create_internal_resources(ID3D12Device* device) {
    uint32_t w = max_upscale_w;
    uint32_t h = max_upscale_h;
    auto uav_flags = D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS;

    // History color: R16G16B16A16_FLOAT
    textures[TEX_HISTORY] = create_texture_2d(device, w, h,
        DXGI_FORMAT_R16G16B16A16_FLOAT, uav_flags,
        D3D12_RESOURCE_STATE_UNORDERED_ACCESS);

    // Recurrent 0: R8G8B8A8_UNORM
    textures[TEX_RECURRENT_0] = create_texture_2d(device, w, h,
        DXGI_FORMAT_R8G8B8A8_UNORM, uav_flags,
        D3D12_RESOURCE_STATE_UNORDERED_ACCESS);

    // History reprojected: R16G16B16A16_FLOAT
    textures[TEX_HISTORY_REPROJECTED] = create_texture_2d(device, w, h,
        DXGI_FORMAT_R16G16B16A16_FLOAT, uav_flags,
        D3D12_RESOURCE_STATE_UNORDERED_ACCESS);

    // Dilated MVs: R16G16_FLOAT
    textures[TEX_DILATED_MV] = create_texture_2d(device, w, h,
        DXGI_FORMAT_R16G16_FLOAT, uav_flags,
        D3D12_RESOURCE_STATE_UNORDERED_ACCESS);

    // RCAS temp: R16G16B16A16_FLOAT
    textures[TEX_RCAS_TEMP] = create_texture_2d(device, w, h,
        DXGI_FORMAT_R16G16B16A16_FLOAT, uav_flags,
        D3D12_RESOURCE_STATE_UNORDERED_ACCESS);

    // Default exposure: R32G32_FLOAT, 1x1, initialized to {1.0, 1.0}
    textures[TEX_DEFAULT_EXPOSURE] = create_texture_2d(device, 1, 1,
        DXGI_FORMAT_R32G32_FLOAT, uav_flags,
        D3D12_RESOURCE_STATE_UNORDERED_ACCESS);

    // Debug blend factor visualization: R32_FLOAT, upscale res
    textures[TEX_DEBUG_BLEND] = create_texture_2d(device, w, h,
        DXGI_FORMAT_R32_FLOAT, uav_flags,
        D3D12_RESOURCE_STATE_UNORDERED_ACCESS);

    // Verify all textures created
    for (int i = 0; i < TEX_COUNT; i++) {
        if (!textures[i]) {
            logf("ERROR: Failed to create internal texture %d\n", i);
            return false;
        }
    }

    // Scratch buffer (raw ByteAddressBuffer)
    size_t scratch_size = get_scratch_size(w, h);
    scratch_buffer = create_buffer(device, scratch_size,
        D3D12_HEAP_TYPE_DEFAULT, D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS,
        D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
    if (!scratch_buffer) {
        logf("ERROR: Failed to create scratch buffer (%zu bytes)\n", scratch_size);
        return false;
    }

    // Select initializer data for current quality preset
    const auto& init_blob = g_initializer_presets[quality_preset];
    logf("Using initializer for preset %d (%zu bytes)\n", quality_preset, init_blob.size);

    // Initializer buffer (raw ByteAddressBuffer, read-only after upload)
    initializer_buffer = create_buffer(device, init_blob.size,
        D3D12_HEAP_TYPE_DEFAULT, D3D12_RESOURCE_FLAG_NONE,
        D3D12_RESOURCE_STATE_COMMON);
    if (!initializer_buffer) {
        logf("ERROR: Failed to create initializer buffer\n");
        return false;
    }

    // Initializer upload buffer (CPU-visible, for one-time copy)
    initializer_upload = create_buffer(device, init_blob.size,
        D3D12_HEAP_TYPE_UPLOAD, D3D12_RESOURCE_FLAG_NONE,
        D3D12_RESOURCE_STATE_GENERIC_READ);
    if (!initializer_upload) {
        logf("ERROR: Failed to create initializer upload buffer\n");
        return false;
    }

    // Copy initializer data to upload buffer
    void* mapped = nullptr;
    HRESULT hr = initializer_upload->Map(0, nullptr, &mapped);
    if (SUCCEEDED(hr)) {
        memcpy(mapped, init_blob.data, init_blob.size);
        initializer_upload->Unmap(0, nullptr);
    }

    // Constant buffer upload (persistently mapped)
    cb_upload = create_buffer(device, CB_UPLOAD_SIZE,
        D3D12_HEAP_TYPE_UPLOAD, D3D12_RESOURCE_FLAG_NONE,
        D3D12_RESOURCE_STATE_GENERIC_READ);
    if (!cb_upload) {
        logf("ERROR: Failed to create CB upload buffer\n");
        return false;
    }
    hr = cb_upload->Map(0, nullptr, &cb_mapped);
    if (FAILED(hr)) {
        logf("ERROR: Failed to map CB upload buffer\n");
        return false;
    }
    memset(cb_mapped, 0, CB_UPLOAD_SIZE);

    // Write encoder1 conv weights to cbPass_Weights region (b1)
    const uint32_t* weights = encoder1_weights_by_preset[quality_preset];
    memcpy(static_cast<uint8_t*>(cb_mapped) + CB_WEIGHTS_OFFSET,
           weights, 256 * sizeof(uint32_t));
    logf("Loaded encoder1 weights for preset %d\n", quality_preset);

    // Write default exposure {1.0, 1.0} for texture upload on first frame
    float default_exposure[2] = { 1.0f, 1.0f };
    memcpy(static_cast<uint8_t*>(cb_mapped) + CB_EXPOSURE_OFFSET,
           default_exposure, sizeof(default_exposure));

#ifndef FSR4_RELEASE
    // Diagnostic readback buffer (for dump_frame)
    diag_readback = create_buffer(device, DIAG_BUFFER_SIZE,
        D3D12_HEAP_TYPE_READBACK, D3D12_RESOURCE_FLAG_NONE,
        D3D12_RESOURCE_STATE_COPY_DEST);
    if (!diag_readback) {
        logf("WARNING: Failed to create diagnostic readback buffer (non-fatal)\n");
    }

    // GPU timestamp query heap + readback buffer (for per-pass profiling)
    {
        D3D12_QUERY_HEAP_DESC qhDesc = {};
        qhDesc.Type = D3D12_QUERY_HEAP_TYPE_TIMESTAMP;
        qhDesc.Count = TIMESTAMP_COUNT;
        HRESULT tshr = device->CreateQueryHeap(&qhDesc, IID_PPV_ARGS(&timestamp_heap));
        if (FAILED(tshr)) {
            logf("WARNING: Failed to create timestamp query heap: 0x%x (non-fatal)\n", tshr);
            timestamp_heap = nullptr;
        }

        // Each timestamp is a uint64_t (8 bytes)
        timestamp_readback = create_buffer(device, TIMESTAMP_COUNT * sizeof(uint64_t),
            D3D12_HEAP_TYPE_READBACK, D3D12_RESOURCE_FLAG_NONE,
            D3D12_RESOURCE_STATE_COPY_DEST);
        if (!timestamp_readback) {
            logf("WARNING: Failed to create timestamp readback buffer (non-fatal)\n");
        }
    }
#endif

    logf("Internal resources created: %ux%u, scratch=%zuKB, init=%zuB\n",
         w, h, scratch_size / 1024, init_blob.size);
    return true;
}

// =========================================================================
// Descriptor Heap
// =========================================================================

bool FSR4D3D12Pipeline::create_descriptor_heap(ID3D12Device* device) {
    D3D12_DESCRIPTOR_HEAP_DESC desc = {};
    desc.NumDescriptors = DESC_TOTAL;
    desc.Type = D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV;
    desc.Flags = D3D12_DESCRIPTOR_HEAP_FLAG_SHADER_VISIBLE;

    HRESULT hr = device->CreateDescriptorHeap(&desc, IID_PPV_ARGS(&srv_uav_heap));
    if (FAILED(hr)) {
        logf("ERROR: Failed to create descriptor heap: 0x%x\n", hr);
        return false;
    }

    descriptor_increment = device->GetDescriptorHandleIncrementSize(
        D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV);

    return true;
}

D3D12_GPU_DESCRIPTOR_HANDLE FSR4D3D12Pipeline::gpu_handle(uint32_t index) const {
    D3D12_GPU_DESCRIPTOR_HANDLE h = srv_uav_heap->GetGPUDescriptorHandleForHeapStart();
    h.ptr += index * descriptor_increment;
    return h;
}

D3D12_CPU_DESCRIPTOR_HANDLE FSR4D3D12Pipeline::cpu_handle(uint32_t index) const {
    D3D12_CPU_DESCRIPTOR_HANDLE h = srv_uav_heap->GetCPUDescriptorHandleForHeapStart();
    h.ptr += index * descriptor_increment;
    return h;
}

void FSR4D3D12Pipeline::setup_internal_descriptors(ID3D12Device* device) {
    logf("setup_internal_descriptors: begin (heap=%p, increment=%u)\n",
         srv_uav_heap, descriptor_increment);

    // Fill descriptor slots for internal resources that don't change per-frame
    // Pre/Post SRV table (t0-t20):
    //   t0  = r_history_color         → TEX_HISTORY
    //   t4  = r_recurrent_0           → TEX_RECURRENT_0
    //   t6  = r_input_exposure        → TEX_DEFAULT_EXPOSURE
    //   t9  = r_reprojected_color     → TEX_HISTORY_REPROJECTED
    //   t12 = r_sr_mv_dilated         → TEX_DILATED_MV

    // First, create null SRVs for ALL slots (prevents GPU page faults)
    D3D12_SHADER_RESOURCE_VIEW_DESC null_srv = {};
    null_srv.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
    null_srv.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
    null_srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
    null_srv.Texture2D.MipLevels = 1;
    for (uint32_t i = 0; i < DESC_SRV_COUNT; i++) {
        device->CreateShaderResourceView(nullptr, &null_srv,
            cpu_handle(DESC_SRV_TABLE_START + i));
    }

    logf("  null SRVs created\n");

    // Create null UAVs for ALL slots
    D3D12_UNORDERED_ACCESS_VIEW_DESC null_uav = {};
    null_uav.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
    null_uav.ViewDimension = D3D12_UAV_DIMENSION_TEXTURE2D;
    for (uint32_t i = 0; i < DESC_UAV_COUNT; i++) {
        device->CreateUnorderedAccessView(nullptr, nullptr, &null_uav,
            cpu_handle(DESC_UAV_TABLE_START + i));
    }

    logf("  null UAVs created\n");

    // t0: History color (float16x3 texture, SRV)
    {
        D3D12_SHADER_RESOURCE_VIEW_DESC srv = {};
        srv.Format = DXGI_FORMAT_R16G16B16A16_FLOAT;
        srv.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
        srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
        srv.Texture2D.MipLevels = 1;
        device->CreateShaderResourceView(textures[TEX_HISTORY], &srv,
            cpu_handle(DESC_SRV_TABLE_START + 0));
    }

    // t4: Recurrent 0 (UNORM, SRV)
    {
        D3D12_SHADER_RESOURCE_VIEW_DESC srv = {};
        srv.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
        srv.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
        srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
        srv.Texture2D.MipLevels = 1;
        device->CreateShaderResourceView(textures[TEX_RECURRENT_0], &srv,
            cpu_handle(DESC_SRV_TABLE_START + 4));
    }

    // t6: Default exposure (R32G32_FLOAT, SRV)
    {
        D3D12_SHADER_RESOURCE_VIEW_DESC srv = {};
        srv.Format = DXGI_FORMAT_R32G32_FLOAT;
        srv.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
        srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
        srv.Texture2D.MipLevels = 1;
        device->CreateShaderResourceView(textures[TEX_DEFAULT_EXPOSURE], &srv,
            cpu_handle(DESC_SRV_TABLE_START + 6));
    }

    // t9: History reprojected (float16x3, SRV)
    {
        D3D12_SHADER_RESOURCE_VIEW_DESC srv = {};
        srv.Format = DXGI_FORMAT_R16G16B16A16_FLOAT;
        srv.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
        srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
        srv.Texture2D.MipLevels = 1;
        device->CreateShaderResourceView(textures[TEX_HISTORY_REPROJECTED], &srv,
            cpu_handle(DESC_SRV_TABLE_START + 9));
    }

    // t12: Dilated MV (R16G16_FLOAT, SRV)
    {
        D3D12_SHADER_RESOURCE_VIEW_DESC srv = {};
        srv.Format = DXGI_FORMAT_R16G16_FLOAT;
        srv.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
        srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
        srv.Texture2D.MipLevels = 1;
        device->CreateShaderResourceView(textures[TEX_DILATED_MV], &srv,
            cpu_handle(DESC_SRV_TABLE_START + 12));
    }

    logf("  SRVs t0,t4,t6,t9,t12 created\n");

    // t18: InitializerBuffer (ByteAddressBuffer SRV, for pre-shader)
    {
        D3D12_SHADER_RESOURCE_VIEW_DESC srv = {};
        srv.Format = DXGI_FORMAT_R32_TYPELESS;
        srv.ViewDimension = D3D12_SRV_DIMENSION_BUFFER;
        srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
        srv.Buffer.FirstElement = 0;
        srv.Buffer.NumElements = (UINT)(g_initializer_presets[quality_preset].size / 4);
        srv.Buffer.Flags = D3D12_BUFFER_SRV_FLAG_RAW;
        device->CreateShaderResourceView(initializer_buffer, &srv,
            cpu_handle(DESC_SRV_TABLE_START + 18));
    }

    logf("  SRV t18 (initializer) created\n");

    // --- UAV descriptors ---

    // u1: History color (write, UAV)
    {
        D3D12_UNORDERED_ACCESS_VIEW_DESC uav = {};
        uav.Format = DXGI_FORMAT_R16G16B16A16_FLOAT;
        uav.ViewDimension = D3D12_UAV_DIMENSION_TEXTURE2D;
        device->CreateUnorderedAccessView(textures[TEX_HISTORY], nullptr, &uav,
            cpu_handle(DESC_UAV_TABLE_START + 1));
    }

    // u3: History reprojected (write, UAV)
    {
        D3D12_UNORDERED_ACCESS_VIEW_DESC uav = {};
        uav.Format = DXGI_FORMAT_R16G16B16A16_FLOAT;
        uav.ViewDimension = D3D12_UAV_DIMENSION_TEXTURE2D;
        device->CreateUnorderedAccessView(textures[TEX_HISTORY_REPROJECTED], nullptr, &uav,
            cpu_handle(DESC_UAV_TABLE_START + 3));
    }

    // u6: Recurrent 0 (write, UAV)
    {
        D3D12_UNORDERED_ACCESS_VIEW_DESC uav = {};
        uav.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
        uav.ViewDimension = D3D12_UAV_DIMENSION_TEXTURE2D;
        device->CreateUnorderedAccessView(textures[TEX_RECURRENT_0], nullptr, &uav,
            cpu_handle(DESC_UAV_TABLE_START + 6));
    }

    // u8: Dilated MV (write, UAV)
    {
        D3D12_UNORDERED_ACCESS_VIEW_DESC uav = {};
        uav.Format = DXGI_FORMAT_R16G16_FLOAT;
        uav.ViewDimension = D3D12_UAV_DIMENSION_TEXTURE2D;
        device->CreateUnorderedAccessView(textures[TEX_DILATED_MV], nullptr, &uav,
            cpu_handle(DESC_UAV_TABLE_START + 8));
    }

    // u11: ScratchBuffer (RWByteAddressBuffer UAV, for pre-shader)
    {
        D3D12_UNORDERED_ACCESS_VIEW_DESC uav = {};
        uav.Format = DXGI_FORMAT_R32_TYPELESS;
        uav.ViewDimension = D3D12_UAV_DIMENSION_BUFFER;
        uav.Buffer.FirstElement = 0;
        uav.Buffer.NumElements = (UINT)(get_scratch_size(max_upscale_w, max_upscale_h) / 4);
        uav.Buffer.Flags = D3D12_BUFFER_UAV_FLAG_RAW;
        device->CreateUnorderedAccessView(scratch_buffer, nullptr, &uav,
            cpu_handle(DESC_UAV_TABLE_START + 11));
    }

    // u12: Debug blend factor visualization (R32_FLOAT, UAV)
    {
        D3D12_UNORDERED_ACCESS_VIEW_DESC uav = {};
        uav.Format = DXGI_FORMAT_R32_FLOAT;
        uav.ViewDimension = D3D12_UAV_DIMENSION_TEXTURE2D;
        device->CreateUnorderedAccessView(textures[TEX_DEBUG_BLEND], nullptr, &uav,
            cpu_handle(DESC_UAV_TABLE_START + 12));
    }

    logf("  UAVs u1,u3,u6,u8,u11,u12 created (main set)\n");

    // --- Populate RCAS and overlay descriptor sets ---
    // NOTE: We do NOT use CopyDescriptorsSimple to clone from the main set.
    // D3D12 spec requires copy sources to be in non-shader-visible heaps,
    // and some games (CP2077, Satisfactory) use D3D12 Agility SDK runtimes
    // that enforce this, causing access violations on shader-visible reads.
    // Instead we create all descriptors directly at each set's offset.

    const uint32_t extra_srv_bases[] = { DESC_RCAS_SRV_START, DESC_OVERLAY_SRV_START };
    const uint32_t extra_uav_bases[] = { DESC_RCAS_UAV_START, DESC_OVERLAY_UAV_START };

    for (int set = 0; set < 2; set++) {
        uint32_t sb = extra_srv_bases[set];
        uint32_t ub = extra_uav_bases[set];

        // Null SRVs for all slots
        for (uint32_t i = 0; i < DESC_SRV_COUNT; i++)
            device->CreateShaderResourceView(nullptr, &null_srv, cpu_handle(sb + i));

        // Null UAVs for all slots
        for (uint32_t i = 0; i < DESC_UAV_COUNT; i++)
            device->CreateUnorderedAccessView(nullptr, nullptr, &null_uav, cpu_handle(ub + i));

        // Internal SRVs (same as main set)
        { // t0: History
            D3D12_SHADER_RESOURCE_VIEW_DESC srv = {};
            srv.Format = DXGI_FORMAT_R16G16B16A16_FLOAT;
            srv.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
            srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
            srv.Texture2D.MipLevels = 1;
            device->CreateShaderResourceView(textures[TEX_HISTORY], &srv, cpu_handle(sb + 0));
        }
        { // t4: Recurrent 0
            D3D12_SHADER_RESOURCE_VIEW_DESC srv = {};
            srv.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
            srv.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
            srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
            srv.Texture2D.MipLevels = 1;
            device->CreateShaderResourceView(textures[TEX_RECURRENT_0], &srv, cpu_handle(sb + 4));
        }
        { // t6: Default exposure
            D3D12_SHADER_RESOURCE_VIEW_DESC srv = {};
            srv.Format = DXGI_FORMAT_R32G32_FLOAT;
            srv.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
            srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
            srv.Texture2D.MipLevels = 1;
            device->CreateShaderResourceView(textures[TEX_DEFAULT_EXPOSURE], &srv, cpu_handle(sb + 6));
        }
        { // t9: History reprojected
            D3D12_SHADER_RESOURCE_VIEW_DESC srv = {};
            srv.Format = DXGI_FORMAT_R16G16B16A16_FLOAT;
            srv.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
            srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
            srv.Texture2D.MipLevels = 1;
            device->CreateShaderResourceView(textures[TEX_HISTORY_REPROJECTED], &srv, cpu_handle(sb + 9));
        }
        { // t12: Dilated MV
            D3D12_SHADER_RESOURCE_VIEW_DESC srv = {};
            srv.Format = DXGI_FORMAT_R16G16_FLOAT;
            srv.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
            srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
            srv.Texture2D.MipLevels = 1;
            device->CreateShaderResourceView(textures[TEX_DILATED_MV], &srv, cpu_handle(sb + 12));
        }
        { // t18: Initializer buffer
            D3D12_SHADER_RESOURCE_VIEW_DESC srv = {};
            srv.Format = DXGI_FORMAT_R32_TYPELESS;
            srv.ViewDimension = D3D12_SRV_DIMENSION_BUFFER;
            srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
            srv.Buffer.FirstElement = 0;
            srv.Buffer.NumElements = (UINT)(g_initializer_presets[quality_preset].size / 4);
            srv.Buffer.Flags = D3D12_BUFFER_SRV_FLAG_RAW;
            device->CreateShaderResourceView(initializer_buffer, &srv, cpu_handle(sb + 18));
        }

        // Internal UAVs (same as main set)
        { // u1: History
            D3D12_UNORDERED_ACCESS_VIEW_DESC uav = {};
            uav.Format = DXGI_FORMAT_R16G16B16A16_FLOAT;
            uav.ViewDimension = D3D12_UAV_DIMENSION_TEXTURE2D;
            device->CreateUnorderedAccessView(textures[TEX_HISTORY], nullptr, &uav, cpu_handle(ub + 1));
        }
        { // u3: History reprojected
            D3D12_UNORDERED_ACCESS_VIEW_DESC uav = {};
            uav.Format = DXGI_FORMAT_R16G16B16A16_FLOAT;
            uav.ViewDimension = D3D12_UAV_DIMENSION_TEXTURE2D;
            device->CreateUnorderedAccessView(textures[TEX_HISTORY_REPROJECTED], nullptr, &uav, cpu_handle(ub + 3));
        }
        { // u6: Recurrent 0
            D3D12_UNORDERED_ACCESS_VIEW_DESC uav = {};
            uav.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
            uav.ViewDimension = D3D12_UAV_DIMENSION_TEXTURE2D;
            device->CreateUnorderedAccessView(textures[TEX_RECURRENT_0], nullptr, &uav, cpu_handle(ub + 6));
        }
        { // u8: Dilated MV
            D3D12_UNORDERED_ACCESS_VIEW_DESC uav = {};
            uav.Format = DXGI_FORMAT_R16G16_FLOAT;
            uav.ViewDimension = D3D12_UAV_DIMENSION_TEXTURE2D;
            device->CreateUnorderedAccessView(textures[TEX_DILATED_MV], nullptr, &uav, cpu_handle(ub + 8));
        }
        { // u11: Scratch buffer
            D3D12_UNORDERED_ACCESS_VIEW_DESC uav = {};
            uav.Format = DXGI_FORMAT_R32_TYPELESS;
            uav.ViewDimension = D3D12_UAV_DIMENSION_BUFFER;
            uav.Buffer.FirstElement = 0;
            uav.Buffer.NumElements = (UINT)(get_scratch_size(max_upscale_w, max_upscale_h) / 4);
            uav.Buffer.Flags = D3D12_BUFFER_UAV_FLAG_RAW;
            device->CreateUnorderedAccessView(scratch_buffer, nullptr, &uav, cpu_handle(ub + 11));
        }
        { // u12: Debug blend
            D3D12_UNORDERED_ACCESS_VIEW_DESC uav = {};
            uav.Format = DXGI_FORMAT_R32_FLOAT;
            uav.ViewDimension = D3D12_UAV_DIMENSION_TEXTURE2D;
            device->CreateUnorderedAccessView(textures[TEX_DEBUG_BLEND], nullptr, &uav, cpu_handle(ub + 12));
        }
    }

    // RCAS override: t18 → RCAS temp texture (instead of initializer buffer)
    {
        D3D12_SHADER_RESOURCE_VIEW_DESC srv = {};
        srv.Format = DXGI_FORMAT_R16G16B16A16_FLOAT;
        srv.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
        srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
        srv.Texture2D.MipLevels = 1;
        device->CreateShaderResourceView(textures[TEX_RCAS_TEMP], &srv,
            cpu_handle(DESC_RCAS_SRV_START + 18));
    }

    logf("  RCAS + overlay descriptor sets created\n");

    // Overlay override: t19 → debug blend visualization (SRV)
    {
        D3D12_SHADER_RESOURCE_VIEW_DESC srv = {};
        srv.Format = DXGI_FORMAT_R32_FLOAT;
        srv.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
        srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
        srv.Texture2D.MipLevels = 1;
        device->CreateShaderResourceView(textures[TEX_DEBUG_BLEND], &srv,
            cpu_handle(DESC_OVERLAY_SRV_START + 19));
    }

    logf("Internal descriptors configured\n");
}

// =========================================================================
// Bind Game Resources (called each frame before dispatch)
// =========================================================================

void FSR4D3D12Pipeline::bind_game_resources(
    ID3D12Device* device,
    ID3D12Resource* color_res, DXGI_FORMAT color_fmt,
    ID3D12Resource* depth_res, DXGI_FORMAT depth_fmt,
    ID3D12Resource* mv_res, DXGI_FORMAT mv_fmt,
    ID3D12Resource* exposure_res,
    ID3D12Resource* output_res, DXGI_FORMAT output_fmt,
    bool enable_sharpening)
{
    // t1: r_velocity (game's motion vectors)
    {
        D3D12_SHADER_RESOURCE_VIEW_DESC srv = {};
        srv.Format = mv_fmt;
        srv.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
        srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
        srv.Texture2D.MipLevels = 1;
        device->CreateShaderResourceView(mv_res, &srv,
            cpu_handle(DESC_SRV_TABLE_START + 1));
    }

    // t2: r_depth (game's depth)
    {
        D3D12_SHADER_RESOURCE_VIEW_DESC srv = {};
        // Handle D24S8 depth by reading 24-bit depth as normalized float
        if (depth_fmt == DXGI_FORMAT_D24_UNORM_S8_UINT ||
            depth_fmt == DXGI_FORMAT_R24G8_TYPELESS ||
            depth_fmt == DXGI_FORMAT_R24_UNORM_X8_TYPELESS) {
            srv.Format = DXGI_FORMAT_R24_UNORM_X8_TYPELESS;
        } else if (depth_fmt == DXGI_FORMAT_D32_FLOAT ||
                   depth_fmt == DXGI_FORMAT_R32_TYPELESS) {
            srv.Format = DXGI_FORMAT_R32_FLOAT;
        } else if (depth_fmt == DXGI_FORMAT_D32_FLOAT_S8X24_UINT ||
                   depth_fmt == DXGI_FORMAT_R32G8X24_TYPELESS) {
            srv.Format = DXGI_FORMAT_R32_FLOAT_X8X24_TYPELESS;
        } else {
            srv.Format = DXGI_FORMAT_R32_FLOAT;  // fallback
        }
        srv.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
        srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
        srv.Texture2D.MipLevels = 1;
        device->CreateShaderResourceView(depth_res, &srv,
            cpu_handle(DESC_SRV_TABLE_START + 2));
    }

    // t3: r_input_color (game's color)
    {
        D3D12_SHADER_RESOURCE_VIEW_DESC srv = {};
        srv.Format = color_fmt;
        srv.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
        srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
        srv.Texture2D.MipLevels = 1;
        device->CreateShaderResourceView(color_res, &srv,
            cpu_handle(DESC_SRV_TABLE_START + 3));
    }

    // t6: r_input_exposure (game's exposure when available, else default)
    if (exposure_res) {
        DXGI_FORMAT exp_fmt = exposure_res->GetDesc().Format;
        D3D12_SHADER_RESOURCE_VIEW_DESC srv = {};
        srv.Format = (exp_fmt != DXGI_FORMAT_UNKNOWN) ? exp_fmt : DXGI_FORMAT_R32G32_FLOAT;
        srv.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
        srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
        srv.Texture2D.MipLevels = 1;
        device->CreateShaderResourceView(exposure_res, &srv,
            cpu_handle(DESC_SRV_TABLE_START + 6));
    }
    // else: keep TEX_DEFAULT_EXPOSURE (initialized to 1.0, 1.0 on first upload)

    // u2: rw_mlsr_output_color (final output or RCAS temp)
    {
        ID3D12Resource* mlsr_output = enable_sharpening ?
            textures[TEX_RCAS_TEMP] : output_res;
        DXGI_FORMAT mlsr_fmt = enable_sharpening ?
            DXGI_FORMAT_R16G16B16A16_FLOAT : output_fmt;

        D3D12_UNORDERED_ACCESS_VIEW_DESC uav = {};
        uav.Format = mlsr_fmt;
        uav.ViewDimension = D3D12_UAV_DIMENSION_TEXTURE2D;
        device->CreateUnorderedAccessView(mlsr_output, nullptr, &uav,
            cpu_handle(DESC_UAV_TABLE_START + 2));
    }

    // u10: rw_output_color_for_rcas (RCAS temp)
    {
        D3D12_UNORDERED_ACCESS_VIEW_DESC uav = {};
        uav.Format = DXGI_FORMAT_R16G16B16A16_FLOAT;
        uav.ViewDimension = D3D12_UAV_DIMENSION_TEXTURE2D;
        device->CreateUnorderedAccessView(textures[TEX_RCAS_TEMP], nullptr, &uav,
            cpu_handle(DESC_UAV_TABLE_START + 10));
    }

    // RCAS set: override u11 with game's output texture
    if (enable_sharpening) {
        D3D12_UNORDERED_ACCESS_VIEW_DESC uav = {};
        uav.Format = output_fmt;
        uav.ViewDimension = D3D12_UAV_DIMENSION_TEXTURE2D;
        device->CreateUnorderedAccessView(output_res, nullptr, &uav,
            cpu_handle(DESC_RCAS_UAV_START + 11));

        // Recreate game resource SRVs in RCAS set (can't copy from shader-visible heap)
        // t1: velocity
        {
            D3D12_SHADER_RESOURCE_VIEW_DESC srv = {};
            srv.Format = mv_fmt;
            srv.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
            srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
            srv.Texture2D.MipLevels = 1;
            device->CreateShaderResourceView(mv_res, &srv,
                cpu_handle(DESC_RCAS_SRV_START + 1));
        }
        // t2: depth
        {
            D3D12_SHADER_RESOURCE_VIEW_DESC srv = {};
            if (depth_fmt == DXGI_FORMAT_D24_UNORM_S8_UINT ||
                depth_fmt == DXGI_FORMAT_R24G8_TYPELESS ||
                depth_fmt == DXGI_FORMAT_R24_UNORM_X8_TYPELESS) {
                srv.Format = DXGI_FORMAT_R24_UNORM_X8_TYPELESS;
            } else if (depth_fmt == DXGI_FORMAT_D32_FLOAT ||
                       depth_fmt == DXGI_FORMAT_R32_TYPELESS) {
                srv.Format = DXGI_FORMAT_R32_FLOAT;
            } else if (depth_fmt == DXGI_FORMAT_D32_FLOAT_S8X24_UINT ||
                       depth_fmt == DXGI_FORMAT_R32G8X24_TYPELESS) {
                srv.Format = DXGI_FORMAT_R32_FLOAT_X8X24_TYPELESS;
            } else {
                srv.Format = DXGI_FORMAT_R32_FLOAT;
            }
            srv.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
            srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
            srv.Texture2D.MipLevels = 1;
            device->CreateShaderResourceView(depth_res, &srv,
                cpu_handle(DESC_RCAS_SRV_START + 2));
        }
        // t3: color
        {
            D3D12_SHADER_RESOURCE_VIEW_DESC srv = {};
            srv.Format = color_fmt;
            srv.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
            srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
            srv.Texture2D.MipLevels = 1;
            device->CreateShaderResourceView(color_res, &srv,
                cpu_handle(DESC_RCAS_SRV_START + 3));
        }
        // t6: exposure
        if (exposure_res) {
            DXGI_FORMAT exp_fmt = exposure_res->GetDesc().Format;
            D3D12_SHADER_RESOURCE_VIEW_DESC srv = {};
            srv.Format = (exp_fmt != DXGI_FORMAT_UNKNOWN) ? exp_fmt : DXGI_FORMAT_R32G32_FLOAT;
            srv.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
            srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
            srv.Texture2D.MipLevels = 1;
            device->CreateShaderResourceView(exposure_res, &srv,
                cpu_handle(DESC_RCAS_SRV_START + 6));
        }
    }

    // Overlay set: u2 always points to game's final output (for read-modify-write)
    {
        D3D12_UNORDERED_ACCESS_VIEW_DESC uav = {};
        uav.Format = output_fmt;
        uav.ViewDimension = D3D12_UAV_DIMENSION_TEXTURE2D;
        device->CreateUnorderedAccessView(output_res, nullptr, &uav,
            cpu_handle(DESC_OVERLAY_UAV_START + 2));
    }
}

// =========================================================================
// Update Constants
// =========================================================================

void FSR4D3D12Pipeline::update_constants(
    const ffxDispatchDescUpscale* desc,
    uint32_t upscale_w, uint32_t upscale_h,
    bool force_reset, uint32_t create_flags)
{
    auto* main = reinterpret_cast<OptimizedConstants*>(
        static_cast<uint8_t*>(cb_mapped) + CB_MAIN_OFFSET);
    auto* rcas = reinterpret_cast<RcasConstants*>(
        static_cast<uint8_t*>(cb_mapped) + CB_RCAS_OFFSET);

    main->inv_size[0] = 1.0f / upscale_w;
    main->inv_size[1] = 1.0f / upscale_h;
    main->scale[0] = (float)upscale_w / desc->renderSize.width;
    main->scale[1] = (float)upscale_h / desc->renderSize.height;
    main->inv_scale[0] = 1.0f / main->scale[0];
    main->inv_scale[1] = 1.0f / main->scale[1];
    main->jitter[0] = desc->jitterOffset.x;
    main->jitter[1] = desc->jitterOffset.y;

    // MV scale: game's MV scale divided by MV texture size
    bool low_res_mv = !(create_flags & 0x2);  // FFX_UPSCALE_ENABLE_DISPLAY_RESOLUTION_MOTION_VECTORS
    uint32_t mv_w = low_res_mv ? desc->renderSize.width : upscale_w;
    uint32_t mv_h = low_res_mv ? desc->renderSize.height : upscale_h;
    main->mv_scale[0] = desc->motionVectorScale.x / mv_w;
    main->mv_scale[1] = desc->motionVectorScale.y / mv_h;

    // Jitter cancellation
    bool jitter_cancel = (create_flags & 0x4) != 0;  // FFX_UPSCALE_ENABLE_MOTION_VECTORS_JITTER_CANCELLATION
    if (jitter_cancel) {
        main->fMotionVectorJitterCancellation[0] =
            (previous_jitter[0] - main->jitter[0]) / mv_w;
        main->fMotionVectorJitterCancellation[1] =
            (previous_jitter[1] - main->jitter[1]) / mv_h;
    } else {
        main->fMotionVectorJitterCancellation[0] = 0;
        main->fMotionVectorJitterCancellation[1] = 0;
    }
    previous_jitter[0] = main->jitter[0];
    previous_jitter[1] = main->jitter[1];

    main->max_renderSize[0] = (float)max_render_w;
    main->max_renderSize[1] = (float)max_render_h;
    main->tex_size[0] = (float)max_upscale_w;
    main->tex_size[1] = (float)max_upscale_h;
    main->width = upscale_w;
    main->height = upscale_h;
    main->reset = desc->reset || force_reset;
    main->width_lr = desc->renderSize.width;
    main->height_lr = desc->renderSize.height;

    // Guard against previous_preExposure being 0 on first frame (would cause NaN/Inf)
    float prev_exposure = main->preExposure;
    main->preExposure = desc->preExposure;
    main->previous_preExposure = (prev_exposure > 0.0f) ? prev_exposure : main->preExposure;
    main->rcas_enabled = desc->enableSharpening;
    main->rcas_sharpness = desc->sharpness;

    // RCAS constants (matches AMD's ffx_provider_fsr4_dx12.cpp line 1948-1949)
    if (desc->enableSharpening) {
        rcas->preExposure = desc->preExposure;
        // Clamp sharpness to [0,1] — values outside this range cause exp2 to blow up
        float sharpness_clamped = desc->sharpness;
        if (sharpness_clamped < 0.0f) sharpness_clamped = 0.0f;
        if (sharpness_clamped > 1.0f) sharpness_clamped = 1.0f;
        // Remap desc->sharpness [0=no sharpening, 1=max] to stops [2=min, 0=max]
        float sharpness_stops = (-2.0f * sharpness_clamped) + 2.0f;
        compute_rcas_config(rcas->config, sharpness_stops);
    }
}

// =========================================================================
// Upload Initializer Data (one-time)
// =========================================================================

void FSR4D3D12Pipeline::ensure_initializer_uploaded(ID3D12GraphicsCommandList* cmd) {
    if (initializer_uploaded) return;

    // Copy initializer from upload heap to default heap
    const auto& init_blob = g_initializer_presets[quality_preset];
    cmd->CopyBufferRegion(initializer_buffer, 0,
                          initializer_upload, 0,
                          init_blob.size);

    // Upload default exposure {1.0, 1.0} to the 1x1 exposure texture
    {
        // Transition exposure texture: UAV → COPY_DEST
        D3D12_RESOURCE_BARRIER b = {};
        b.Type = D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;
        b.Transition.pResource = textures[TEX_DEFAULT_EXPOSURE];
        b.Transition.StateBefore = D3D12_RESOURCE_STATE_UNORDERED_ACCESS;
        b.Transition.StateAfter = D3D12_RESOURCE_STATE_COPY_DEST;
        b.Transition.Subresource = D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES;
        cmd->ResourceBarrier(1, &b);

        // Copy from upload buffer to texture
        D3D12_TEXTURE_COPY_LOCATION src = {};
        src.pResource = cb_upload;
        src.Type = D3D12_TEXTURE_COPY_TYPE_PLACED_FOOTPRINT;
        src.PlacedFootprint.Offset = CB_EXPOSURE_OFFSET;
        src.PlacedFootprint.Footprint.Format = DXGI_FORMAT_R32G32_FLOAT;
        src.PlacedFootprint.Footprint.Width = 1;
        src.PlacedFootprint.Footprint.Height = 1;
        src.PlacedFootprint.Footprint.Depth = 1;
        src.PlacedFootprint.Footprint.RowPitch = 256;  // Must be D3D12_TEXTURE_DATA_PITCH_ALIGNMENT

        D3D12_TEXTURE_COPY_LOCATION dst = {};
        dst.pResource = textures[TEX_DEFAULT_EXPOSURE];
        dst.Type = D3D12_TEXTURE_COPY_TYPE_SUBRESOURCE_INDEX;
        dst.SubresourceIndex = 0;

        cmd->CopyTextureRegion(&dst, 0, 0, 0, &src, nullptr);

        // Transition exposure texture: COPY_DEST → NON_PIXEL_SHADER_RESOURCE
        b.Transition.StateBefore = D3D12_RESOURCE_STATE_COPY_DEST;
        b.Transition.StateAfter = D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE;
        cmd->ResourceBarrier(1, &b);
    }

    // Transition initializer buffer to SRV
    D3D12_RESOURCE_BARRIER barrier = {};
    barrier.Type = D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;
    barrier.Transition.pResource = initializer_buffer;
    barrier.Transition.StateBefore = D3D12_RESOURCE_STATE_COPY_DEST;
    barrier.Transition.StateAfter = D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE;
    barrier.Transition.Subresource = D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES;
    cmd->ResourceBarrier(1, &barrier);

    initializer_uploaded = true;
    logf("Initializer data uploaded (%zu bytes), default exposure initialized\n",
         init_blob.size);
}

// =========================================================================
// Update Default Exposure (per-frame when no game exposure resource)
// =========================================================================

void FSR4D3D12Pipeline::update_default_exposure(
    ID3D12GraphicsCommandList* cmd, float preExposure)
{
    // Write {preExposure, preExposure} to upload buffer at exposure offset
    float exposure_data[2] = { preExposure, preExposure };
    memcpy(static_cast<uint8_t*>(cb_mapped) + CB_EXPOSURE_OFFSET,
           exposure_data, sizeof(exposure_data));

    // Transition exposure texture: SRV → COPY_DEST
    D3D12_RESOURCE_BARRIER b = {};
    b.Type = D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;
    b.Transition.pResource = textures[TEX_DEFAULT_EXPOSURE];
    b.Transition.Subresource = D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES;
    b.Transition.StateBefore = D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE;
    b.Transition.StateAfter = D3D12_RESOURCE_STATE_COPY_DEST;
    cmd->ResourceBarrier(1, &b);

    // Copy from upload buffer to texture
    D3D12_TEXTURE_COPY_LOCATION src = {};
    src.pResource = cb_upload;
    src.Type = D3D12_TEXTURE_COPY_TYPE_PLACED_FOOTPRINT;
    src.PlacedFootprint.Offset = CB_EXPOSURE_OFFSET;
    src.PlacedFootprint.Footprint.Format = DXGI_FORMAT_R32G32_FLOAT;
    src.PlacedFootprint.Footprint.Width = 1;
    src.PlacedFootprint.Footprint.Height = 1;
    src.PlacedFootprint.Footprint.Depth = 1;
    src.PlacedFootprint.Footprint.RowPitch = 256;

    D3D12_TEXTURE_COPY_LOCATION dst = {};
    dst.pResource = textures[TEX_DEFAULT_EXPOSURE];
    dst.Type = D3D12_TEXTURE_COPY_TYPE_SUBRESOURCE_INDEX;
    dst.SubresourceIndex = 0;

    cmd->CopyTextureRegion(&dst, 0, 0, 0, &src, nullptr);

    // Transition exposure texture: COPY_DEST → SRV
    b.Transition.StateBefore = D3D12_RESOURCE_STATE_COPY_DEST;
    b.Transition.StateAfter = D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE;
    cmd->ResourceBarrier(1, &b);
}

// =========================================================================
// UAV Barriers
// =========================================================================

void FSR4D3D12Pipeline::uav_barrier(ID3D12GraphicsCommandList* cmd, ID3D12Resource* resource) {
    D3D12_RESOURCE_BARRIER barrier = {};
    barrier.Type = D3D12_RESOURCE_BARRIER_TYPE_UAV;
    barrier.UAV.pResource = resource;
    cmd->ResourceBarrier(1, &barrier);
}

void FSR4D3D12Pipeline::uav_barrier_all(ID3D12GraphicsCommandList* cmd) {
    D3D12_RESOURCE_BARRIER barrier = {};
    barrier.Type = D3D12_RESOURCE_BARRIER_TYPE_UAV;
    barrier.UAV.pResource = nullptr;  // All UAV resources
    cmd->ResourceBarrier(1, &barrier);
}

// =========================================================================
// Dispatch (record compute passes on game's command list)
// =========================================================================

void FSR4D3D12Pipeline::dispatch(
    ID3D12GraphicsCommandList* cmd,
    uint32_t render_w, uint32_t render_h,
    uint32_t upscale_w, uint32_t upscale_h,
    bool enable_sharpening,
    bool debug_blend)
{
    // Ensure initializer data is on GPU
    ensure_initializer_uploaded(cmd);

    // Compute encoder resolutions (downsampled by 2x, 4x, 8x from upscale)
    uint32_t enc_w[3], enc_h[3];
    for (int i = 0; i < 3; i++) {
        enc_w[i] = upscale_w / (1u << (i + 1));
        enc_h[i] = upscale_h / (1u << (i + 1));
    }

    D3D12_GPU_VIRTUAL_ADDRESS scratch_va = scratch_buffer->GetGPUVirtualAddress();
    D3D12_GPU_VIRTUAL_ADDRESS init_va = initializer_buffer->GetGPUVirtualAddress();
    D3D12_GPU_VIRTUAL_ADDRESS cb_main_va = cb_upload->GetGPUVirtualAddress() + CB_MAIN_OFFSET;
    D3D12_GPU_VIRTUAL_ADDRESS cb_rcas_va = cb_upload->GetGPUVirtualAddress() + CB_RCAS_OFFSET;
    D3D12_GPU_VIRTUAL_ADDRESS cb_weights_va = cb_upload->GetGPUVirtualAddress() + CB_WEIGHTS_OFFSET;

    // Set descriptor heap (shared for all passes)
    ID3D12DescriptorHeap* heaps[] = { srv_uav_heap };
    cmd->SetDescriptorHeaps(1, heaps);

    // =====================================================================
    // Resource state transitions: Pre shader reads internal textures as SRV
    // Pre reads: history(t0), recurrent_0(t4) as SRV
    // Pre writes: reprojected(u3), dilated_mv(u8), scratch(u11) as UAV
    // =====================================================================
    {
        D3D12_RESOURCE_BARRIER barriers[2];
        int n = 0;
        // history: UAV → SRV (Pre reads at t0)
        barriers[n++] = make_transition(textures[TEX_HISTORY],
            D3D12_RESOURCE_STATE_UNORDERED_ACCESS,
            D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
        // recurrent_0: UAV → SRV (Pre reads at t4)
        barriers[n++] = make_transition(textures[TEX_RECURRENT_0],
            D3D12_RESOURCE_STATE_UNORDERED_ACCESS,
            D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
        cmd->ResourceBarrier(n, barriers);
    }

#ifndef FSR4_RELEASE
    // GPU timestamp profiling: index 0 = before Pre
    uint32_t ts_idx = 0;
    if (timestamp_heap) {
        cmd->EndQuery(timestamp_heap, D3D12_QUERY_TYPE_TIMESTAMP, ts_idx++);
    }
#endif

    // ===== PRE PASS =====
    cmd->SetComputeRootSignature(pre_post_root_sig);
    cmd->SetPipelineState(pso[PSO_PRE]);
    cmd->SetComputeRootConstantBufferView(PP_ROOT_CBV_B0, cb_main_va);
    cmd->SetComputeRootConstantBufferView(PP_ROOT_CBV_B1, cb_weights_va);
    cmd->SetComputeRootDescriptorTable(PP_SRV_TABLE,
        gpu_handle(DESC_SRV_TABLE_START));
    cmd->SetComputeRootDescriptorTable(PP_UAV_TABLE,
        gpu_handle(DESC_UAV_TABLE_START));
    // Pre-shader: [numthreads(256, 1, 1)] with GROUP_SIZE_=16 (16*16=256)
    cmd->Dispatch(round_up_div(upscale_w, 16u), round_up_div(upscale_h, 16u), 1);

#ifndef FSR4_RELEASE
    // GPU timestamp: after Pre (index 1)
    if (timestamp_heap) {
        cmd->EndQuery(timestamp_heap, D3D12_QUERY_TYPE_TIMESTAMP, ts_idx++);
    }
#endif

    // =====================================================================
    // Between Pre and Model: transition history + recurrent back to UAV
    // (Post pass will write them), and UAV barrier on scratch
    // =====================================================================
    {
        D3D12_RESOURCE_BARRIER barriers[3];
        int n = 0;
        // history: SRV → UAV (Post will write at u1)
        barriers[n++] = make_transition(textures[TEX_HISTORY],
            D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE,
            D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
        // recurrent_0: SRV → UAV (Post will write at u6)
        barriers[n++] = make_transition(textures[TEX_RECURRENT_0],
            D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE,
            D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
        // UAV barrier on scratch (Pre wrote, Model reads)
        barriers[n].Type = D3D12_RESOURCE_BARRIER_TYPE_UAV;
        barriers[n].Flags = D3D12_RESOURCE_BARRIER_FLAG_NONE;
        barriers[n].UAV.pResource = scratch_buffer;
        n++;
        cmd->ResourceBarrier(n, barriers);
    }

    // ===== MODEL PASSES 1-12 =====
    cmd->SetComputeRootSignature(model_root_sig);

    // All model passes use the same buffers:
    // t0 = scratch (read), t1 = initializer, u0 = scratch (write), u1 = scratch
    cmd->SetComputeRootShaderResourceView(MODEL_ROOT_SRV_T0, scratch_va);
    cmd->SetComputeRootShaderResourceView(MODEL_ROOT_SRV_T1, init_va);
    cmd->SetComputeRootUnorderedAccessView(MODEL_ROOT_UAV_U0, scratch_va);
    cmd->SetComputeRootUnorderedAccessView(MODEL_ROOT_UAV_U1, scratch_va);

    // Dispatch sizes for non-WMMA (DOT4) path
    // From AMD's ffx_provider_fsr4_dx12.cpp lines 1676-1694
    struct { uint32_t x, y, z; } dispatch_sizes[12];

    dispatch_sizes[0]  = { round_up_div(enc_w[0], 64u), enc_h[0], 1 };  // Pass 1
    dispatch_sizes[1]  = dispatch_sizes[0];                               // Pass 2
    dispatch_sizes[2]  = { round_up_div(enc_w[1], 64u), enc_h[1], 1 };  // Pass 3
    dispatch_sizes[3]  = dispatch_sizes[2];                               // Pass 4
    dispatch_sizes[4]  = dispatch_sizes[2];                               // Pass 5
    dispatch_sizes[5]  = { round_up_div(enc_w[2], 64u), enc_h[2], 1 };  // Pass 6
    dispatch_sizes[6]  = dispatch_sizes[5];                               // Pass 7
    dispatch_sizes[7]  = dispatch_sizes[5];                               // Pass 8
    dispatch_sizes[8]  = { round_up_div(enc_w[2], 8u),                   // Pass 9 (bottleneck)
                           round_up_div(enc_h[2], 8u), 1 };
    dispatch_sizes[9]  = { round_up_div(enc_w[1], 64u), enc_h[1], 1 };  // Pass 10
    dispatch_sizes[10] = dispatch_sizes[9];                               // Pass 11
    dispatch_sizes[11] = { round_up_div(enc_w[0], 64u), enc_h[0], 1 };  // Pass 12

    for (int i = 0; i < 12; i++) {
        cmd->SetPipelineState(pso[PSO_PASS_1 + i]);
        cmd->Dispatch(dispatch_sizes[i].x, dispatch_sizes[i].y, dispatch_sizes[i].z);

#ifndef FSR4_RELEASE
        // GPU timestamp: after Model pass i+1 (indices 2-13)
        if (timestamp_heap) {
            cmd->EndQuery(timestamp_heap, D3D12_QUERY_TYPE_TIMESTAMP, ts_idx++);
        }
#endif

        if (i < 11) {
            // UAV barrier between model passes (scratch buffer)
            uav_barrier(cmd, scratch_buffer);
        }
    }

    // =====================================================================
    // Between Model and Post: batch Model12's trailing scratch UAV barrier
    // with the texture transitions Post needs.
    // Post reads reprojected(t9) and dilated_mv(t12) as SRV.
    // Post writes: history(u1), output(u2), recurrent(u6), scratch(u11) as UAV.
    // =====================================================================
    {
        D3D12_RESOURCE_BARRIER barriers[3];
        // Scratch UAV barrier (Model12 wrote, Post reads via u11)
        barriers[0].Type = D3D12_RESOURCE_BARRIER_TYPE_UAV;
        barriers[0].Flags = D3D12_RESOURCE_BARRIER_FLAG_NONE;
        barriers[0].UAV.pResource = scratch_buffer;
        // reprojected: UAV → SRV (Post reads at t9)
        barriers[1] = make_transition(textures[TEX_HISTORY_REPROJECTED],
            D3D12_RESOURCE_STATE_UNORDERED_ACCESS,
            D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
        // dilated_mv: UAV → SRV (Post reads at t12)
        barriers[2] = make_transition(textures[TEX_DILATED_MV],
            D3D12_RESOURCE_STATE_UNORDERED_ACCESS,
            D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
        cmd->ResourceBarrier(3, barriers);
    }

    // ===== POST PASS =====
    cmd->SetComputeRootSignature(pre_post_root_sig);
    if (debug_blend)
        cmd->SetPipelineState(pso[PSO_POST_DEBUG]);
    else
        cmd->SetPipelineState(use_fast_exp ? pso[PSO_POST] : pso_post_normal);
    cmd->SetComputeRootConstantBufferView(PP_ROOT_CBV_B0, cb_main_va);
    cmd->SetComputeRootConstantBufferView(PP_ROOT_CBV_B1, cb_weights_va);
    cmd->SetComputeRootDescriptorTable(PP_SRV_TABLE,
        gpu_handle(DESC_SRV_TABLE_START));
    cmd->SetComputeRootDescriptorTable(PP_UAV_TABLE,
        gpu_handle(DESC_UAV_TABLE_START));
    // Post-shader: [numthreads(8, 8, 1)], 2 pixels per thread per dim
    cmd->Dispatch(round_up_div(upscale_w, 16u), round_up_div(upscale_h, 16u), 1);

#ifndef FSR4_RELEASE
    // GPU timestamp: after Post (index 14)
    if (timestamp_heap) {
        cmd->EndQuery(timestamp_heap, D3D12_QUERY_TYPE_TIMESTAMP, ts_idx++);
    }
#endif

    // =====================================================================
    // After Post: transition reprojected and dilated_mv back to UAV for next frame
    // history and recurrent are already in UAV (Post wrote them as UAV)
    // =====================================================================
    {
        D3D12_RESOURCE_BARRIER barriers[2];
        barriers[0] = make_transition(textures[TEX_HISTORY_REPROJECTED],
            D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE,
            D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
        barriers[1] = make_transition(textures[TEX_DILATED_MV],
            D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE,
            D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
        cmd->ResourceBarrier(2, barriers);
    }

    // ===== RCAS (optional) =====
    if (enable_sharpening) {
        uav_barrier_all(cmd);

        cmd->SetPipelineState(pso[PSO_RCAS]);
        // RCAS binds cbRCAS at b0 (NOT b2 — rcas.hlsl overrides the define)
        cmd->SetComputeRootConstantBufferView(PP_ROOT_CBV_B0, cb_rcas_va);
        cmd->SetComputeRootConstantBufferView(PP_ROOT_CBV_B1, cb_weights_va);
        // RCAS uses different descriptor tables (t18=rcas_temp, u11=output)
        cmd->SetComputeRootDescriptorTable(PP_SRV_TABLE,
            gpu_handle(DESC_RCAS_SRV_START));
        cmd->SetComputeRootDescriptorTable(PP_UAV_TABLE,
            gpu_handle(DESC_RCAS_UAV_START));
        cmd->Dispatch(round_up_div(upscale_w, 16u), round_up_div(upscale_h, 16u), 1);

#ifndef FSR4_RELEASE
        // GPU timestamp: after RCAS (index 15)
        if (timestamp_heap) {
            cmd->EndQuery(timestamp_heap, D3D12_QUERY_TYPE_TIMESTAMP, ts_idx++);
        }
#endif
    }

    // ===== DEBUG BLEND OVERLAY (optional) =====
    if (debug_blend) {
        // UAV barrier: Post/RCAS wrote output, overlay reads/writes it
        uav_barrier_all(cmd);

        // Transition debug viz: UAV → SRV (Post wrote blend factor, overlay reads)
        D3D12_RESOURCE_BARRIER b = make_transition(textures[TEX_DEBUG_BLEND],
            D3D12_RESOURCE_STATE_UNORDERED_ACCESS,
            D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
        cmd->ResourceBarrier(1, &b);

        cmd->SetComputeRootSignature(pre_post_root_sig);
        cmd->SetPipelineState(pso[PSO_DEBUG_OVERLAY]);
        cmd->SetComputeRootConstantBufferView(PP_ROOT_CBV_B0, cb_main_va);
        cmd->SetComputeRootConstantBufferView(PP_ROOT_CBV_B1, cb_weights_va);
        cmd->SetComputeRootDescriptorTable(PP_SRV_TABLE,
            gpu_handle(DESC_OVERLAY_SRV_START));
        cmd->SetComputeRootDescriptorTable(PP_UAV_TABLE,
            gpu_handle(DESC_OVERLAY_UAV_START));
        // [numthreads(8, 8, 1)], 1 pixel per thread
        cmd->Dispatch(round_up_div(upscale_w, 8u), round_up_div(upscale_h, 8u), 1);

        // Transition debug viz back to UAV for next frame
        b = make_transition(textures[TEX_DEBUG_BLEND],
            D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE,
            D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
        cmd->ResourceBarrier(1, &b);
    }

#ifndef FSR4_RELEASE
    // Resolve all timestamp queries into readback buffer
    if (timestamp_heap && timestamp_readback && ts_idx > 0) {
        cmd->ResolveQueryData(timestamp_heap, D3D12_QUERY_TYPE_TIMESTAMP,
                              0, ts_idx, timestamp_readback, 0);
        timestamp_pass_count = ts_idx;
        timestamp_pending = true;
    }
#endif
}

#ifndef FSR4_RELEASE
// =========================================================================
// GPU Timestamp Profiling (debug only)
// =========================================================================

void FSR4D3D12Pipeline::resolve_timestamps(ID3D12GraphicsCommandList* cmd, uint32_t count) {
    // Already handled inline in dispatch()
    (void)cmd; (void)count;
}

void FSR4D3D12Pipeline::read_timestamp_results() {
    if (!timestamp_pending || !timestamp_readback || timestamp_pass_count < 2) {
        timestamp_pending = false;
        return;
    }

    uint64_t* data = nullptr;
    D3D12_RANGE range = { 0, timestamp_pass_count * sizeof(uint64_t) };
    HRESULT hr = timestamp_readback->Map(0, &range, reinterpret_cast<void**>(&data));
    if (FAILED(hr) || !data) {
        timestamp_pending = false;
        return;
    }

    // Convert ticks to milliseconds
    double tick_to_ms = (gpu_timestamp_frequency > 0)
        ? 1000.0 / static_cast<double>(gpu_timestamp_frequency)
        : 0.0;

    // Pass names for logging
    static const char* pass_names[] = {
        "Pre", "Model1", "Model2", "Model3", "Model4", "Model5", "Model6",
        "Model7", "Model8", "Model9", "Model10", "Model11", "Model12",
        "Post", "RCAS"
    };

    double total_ms = 0.0;
    uint32_t num_passes = timestamp_pass_count - 1; // N timestamps = N-1 intervals

    logf("GPU PROFILE (frame %d): %u passes, freq=%llu Hz\n",
         frame_index, num_passes, (unsigned long long)gpu_timestamp_frequency);

    for (uint32_t i = 0; i < num_passes && i < 15; i++) {
        uint64_t dt = data[i + 1] - data[i];
        double ms = static_cast<double>(dt) * tick_to_ms;
        total_ms += ms;
        logf("  %-8s  %7.3f ms  (%llu ticks)\n",
             pass_names[i], ms, (unsigned long long)dt);
    }
    logf("  TOTAL     %7.3f ms\n", total_ms);

    // Also print to console for live monitoring
    printf("[FSR4 GPU] frame %d: ", frame_index);
    for (uint32_t i = 0; i < num_passes && i < 15; i++) {
        uint64_t dt = data[i + 1] - data[i];
        double ms = static_cast<double>(dt) * tick_to_ms;
        printf("%s=%.2f ", pass_names[i], ms);
    }
    printf("TOTAL=%.2f ms\n", total_ms);

    D3D12_RANGE empty = { 0, 0 };
    timestamp_readback->Unmap(0, &empty);
    timestamp_pending = false;
}

// =========================================================================
// GPU Diagnostic Readback (debug only)
// =========================================================================

// Helper to convert half-float to float
static float half_to_float(uint16_t h) {
    uint32_t sign = (h >> 15) & 1;
    uint32_t exp  = (h >> 10) & 0x1F;
    uint32_t mant = h & 0x3FF;
    if (exp == 0) {
        if (mant == 0) return sign ? -0.0f : 0.0f;
        // Denormalized
        float f = (float)mant / 1024.0f;
        return sign ? -f * (1.0f / 16384.0f) : f * (1.0f / 16384.0f);
    }
    if (exp == 31) return sign ? -INFINITY : INFINITY;
    float f;
    uint32_t fp32 = (sign << 31) | ((exp + 112) << 23) | (mant << 13);
    memcpy(&f, &fp32, 4);
    return f;
}

void FSR4D3D12Pipeline::issue_diagnostic_readback(
    ID3D12GraphicsCommandList* cmd,
    ID3D12Resource* mv_res, DXGI_FORMAT mv_fmt,
    ID3D12Resource* output_res, DXGI_FORMAT output_fmt,
    ID3D12Resource* color_res, DXGI_FORMAT color_fmt,
    ID3D12Resource* exposure_res, DXGI_FORMAT exposure_fmt,
    uint32_t render_w, uint32_t render_h)
{
    if (!diag_readback) return;

    diag_center_x = max_upscale_w / 2;
    diag_center_y = max_upscale_h / 2;

    // Helper: copy a single pixel from a 2D texture to the readback buffer
    auto copy_pixel = [&](ID3D12Resource* src, DXGI_FORMAT fmt,
                          uint32_t px, uint32_t py, uint32_t dst_offset)
    {
        D3D12_TEXTURE_COPY_LOCATION src_loc = {};
        src_loc.pResource = src;
        src_loc.Type = D3D12_TEXTURE_COPY_TYPE_SUBRESOURCE_INDEX;
        src_loc.SubresourceIndex = 0;

        D3D12_TEXTURE_COPY_LOCATION dst_loc = {};
        dst_loc.pResource = diag_readback;
        dst_loc.Type = D3D12_TEXTURE_COPY_TYPE_PLACED_FOOTPRINT;
        dst_loc.PlacedFootprint.Offset = dst_offset;
        dst_loc.PlacedFootprint.Footprint.Format = fmt;
        dst_loc.PlacedFootprint.Footprint.Width = 1;
        dst_loc.PlacedFootprint.Footprint.Height = 1;
        dst_loc.PlacedFootprint.Footprint.Depth = 1;
        dst_loc.PlacedFootprint.Footprint.RowPitch = 256;

        D3D12_BOX box = { px, py, 0, px + 1, py + 1, 1 };
        cmd->CopyTextureRegion(&dst_loc, 0, 0, 0, &src_loc, &box);
    };

    // Transition resources → COPY_SOURCE
    D3D12_RESOURCE_BARRIER barriers[10];
    int n = 0;
    // Internal textures (UAV → COPY_SOURCE)
    barriers[n++] = make_transition(textures[TEX_HISTORY],
        D3D12_RESOURCE_STATE_UNORDERED_ACCESS, D3D12_RESOURCE_STATE_COPY_SOURCE);
    barriers[n++] = make_transition(textures[TEX_HISTORY_REPROJECTED],
        D3D12_RESOURCE_STATE_UNORDERED_ACCESS, D3D12_RESOURCE_STATE_COPY_SOURCE);
    barriers[n++] = make_transition(textures[TEX_RECURRENT_0],
        D3D12_RESOURCE_STATE_UNORDERED_ACCESS, D3D12_RESOURCE_STATE_COPY_SOURCE);
    barriers[n++] = make_transition(textures[TEX_DILATED_MV],
        D3D12_RESOURCE_STATE_UNORDERED_ACCESS, D3D12_RESOURCE_STATE_COPY_SOURCE);
    barriers[n++] = make_transition(textures[TEX_RCAS_TEMP],
        D3D12_RESOURCE_STATE_UNORDERED_ACCESS, D3D12_RESOURCE_STATE_COPY_SOURCE);
    // Game resources (SRV or UAV → COPY_SOURCE)
    if (mv_res) {
        barriers[n++] = make_transition(mv_res,
            D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE, D3D12_RESOURCE_STATE_COPY_SOURCE);
    }
    if (output_res) {
        barriers[n++] = make_transition(output_res,
            D3D12_RESOURCE_STATE_UNORDERED_ACCESS, D3D12_RESOURCE_STATE_COPY_SOURCE);
    }
    if (color_res) {
        barriers[n++] = make_transition(color_res,
            D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE, D3D12_RESOURCE_STATE_COPY_SOURCE);
    }
    if (exposure_res) {
        barriers[n++] = make_transition(exposure_res,
            D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE, D3D12_RESOURCE_STATE_COPY_SOURCE);
    }
    cmd->ResourceBarrier(n, barriers);

    // Copy center pixel from internal textures (at output resolution)
    copy_pixel(textures[TEX_HISTORY], DXGI_FORMAT_R16G16B16A16_FLOAT,
               diag_center_x, diag_center_y, DIAG_HISTORY_OFFSET);
    copy_pixel(textures[TEX_HISTORY_REPROJECTED], DXGI_FORMAT_R16G16B16A16_FLOAT,
               diag_center_x, diag_center_y, DIAG_REPROJECTED_OFFSET);
    copy_pixel(textures[TEX_RECURRENT_0], DXGI_FORMAT_R8G8B8A8_UNORM,
               diag_center_x, diag_center_y, DIAG_RECURRENT_OFFSET);
    copy_pixel(textures[TEX_DILATED_MV], DXGI_FORMAT_R16G16_FLOAT,
               diag_center_x, diag_center_y, DIAG_DILATED_MV_OFFSET);
    copy_pixel(textures[TEX_RCAS_TEMP], DXGI_FORMAT_R16G16B16A16_FLOAT,
               diag_center_x, diag_center_y, DIAG_RCAS_TEMP_OFFSET);

    // Copy 4 pixels from game's RAW MV texture (at render resolution)
    if (mv_res) {
        copy_pixel(mv_res, mv_fmt, render_w / 2, render_h / 2, DIAG_MV_CENTER_OFFSET);
        copy_pixel(mv_res, mv_fmt, render_w / 4, render_h / 4, DIAG_MV_QUARTER_OFFSET);
        copy_pixel(mv_res, mv_fmt, 3 * render_w / 4, 3 * render_h / 4, DIAG_MV_3QUARTER_OFFSET);
        copy_pixel(mv_res, mv_fmt, render_w / 8, render_h / 8, DIAG_MV_CORNER_OFFSET);
    }

    // Copy center pixel from output (at upscale resolution)
    if (output_res) {
        copy_pixel(output_res, output_fmt, diag_center_x, diag_center_y, DIAG_OUTPUT_OFFSET);
    }

    // Copy center pixel from game's input color (at render resolution)
    if (color_res) {
        copy_pixel(color_res, color_fmt, render_w / 2, render_h / 2, DIAG_INPUT_COLOR_OFFSET);
    }

    // Copy exposure texture pixel (0,0) — 1x1 texture
    if (exposure_res) {
        copy_pixel(exposure_res, exposure_fmt, 0, 0, DIAG_EXPOSURE_OFFSET);
    }

    // Transition back
    n = 0;
    barriers[n++] = make_transition(textures[TEX_HISTORY],
        D3D12_RESOURCE_STATE_COPY_SOURCE, D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
    barriers[n++] = make_transition(textures[TEX_HISTORY_REPROJECTED],
        D3D12_RESOURCE_STATE_COPY_SOURCE, D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
    barriers[n++] = make_transition(textures[TEX_RECURRENT_0],
        D3D12_RESOURCE_STATE_COPY_SOURCE, D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
    barriers[n++] = make_transition(textures[TEX_DILATED_MV],
        D3D12_RESOURCE_STATE_COPY_SOURCE, D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
    barriers[n++] = make_transition(textures[TEX_RCAS_TEMP],
        D3D12_RESOURCE_STATE_COPY_SOURCE, D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
    if (mv_res) {
        barriers[n++] = make_transition(mv_res,
            D3D12_RESOURCE_STATE_COPY_SOURCE, D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
    }
    if (output_res) {
        barriers[n++] = make_transition(output_res,
            D3D12_RESOURCE_STATE_COPY_SOURCE, D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
    }
    if (color_res) {
        barriers[n++] = make_transition(color_res,
            D3D12_RESOURCE_STATE_COPY_SOURCE, D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
    }
    if (exposure_res) {
        barriers[n++] = make_transition(exposure_res,
            D3D12_RESOURCE_STATE_COPY_SOURCE, D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
    }
    cmd->ResourceBarrier(n, barriers);

    diag_pending = true;
}

void FSR4D3D12Pipeline::read_diagnostic_results() {
    if (!diag_pending || !diag_readback) return;
    diag_pending = false;

    void* mapped = nullptr;
    D3D12_RANGE range = { 0, DIAG_BUFFER_SIZE };
    HRESULT hr = diag_readback->Map(0, &range, &mapped);
    if (FAILED(hr)) {
        logf("DIAG: Failed to map readback buffer\n");
        return;
    }

    auto* data = static_cast<const uint8_t*>(mapped);

    // History color (R16G16B16A16_FLOAT)
    const auto* hist = reinterpret_cast<const uint16_t*>(data + DIAG_HISTORY_OFFSET);
    float hist_r = half_to_float(hist[0]), hist_g = half_to_float(hist[1]);
    float hist_b = half_to_float(hist[2]), hist_a = half_to_float(hist[3]);

    // Reprojected color (R16G16B16A16_FLOAT)
    const auto* repr = reinterpret_cast<const uint16_t*>(data + DIAG_REPROJECTED_OFFSET);
    float repr_r = half_to_float(repr[0]), repr_g = half_to_float(repr[1]);
    float repr_b = half_to_float(repr[2]), repr_a = half_to_float(repr[3]);

    // Raw game MV at 4 positions (R16G16_FLOAT) — read hex values
    struct { const char* name; uint32_t offset; uint16_t raw[2]; float val[2]; } mv_samples[] = {
        { "center",   DIAG_MV_CENTER_OFFSET,   {}, {} },
        { "quarter",  DIAG_MV_QUARTER_OFFSET,  {}, {} },
        { "3quarter", DIAG_MV_3QUARTER_OFFSET, {}, {} },
        { "corner",   DIAG_MV_CORNER_OFFSET,   {}, {} },
    };
    for (auto& s : mv_samples) {
        const auto* mv = reinterpret_cast<const uint16_t*>(data + s.offset);
        s.raw[0] = mv[0]; s.raw[1] = mv[1];
        s.val[0] = half_to_float(mv[0]); s.val[1] = half_to_float(mv[1]);
    }

    // Recurrent (R8G8B8A8_UNORM)
    const auto* rec = data + DIAG_RECURRENT_OFFSET;
    float rec_r = rec[0] / 255.0f, rec_g = rec[1] / 255.0f;
    float rec_b = rec[2] / 255.0f, rec_a = rec[3] / 255.0f;

    // Output pixel (R16G16B16A16_FLOAT at upscale-res center)
    const auto* out = reinterpret_cast<const uint16_t*>(data + DIAG_OUTPUT_OFFSET);
    float out_r = half_to_float(out[0]), out_g = half_to_float(out[1]);
    float out_b = half_to_float(out[2]), out_a = half_to_float(out[3]);

    // Input color pixel (R16G16B16A16_FLOAT at render-res center)
    const auto* inp = reinterpret_cast<const uint16_t*>(data + DIAG_INPUT_COLOR_OFFSET);
    float inp_r = half_to_float(inp[0]), inp_g = half_to_float(inp[1]);
    float inp_b = half_to_float(inp[2]), inp_a = half_to_float(inp[3]);

    // Exposure texture — could be R16_FLOAT (KCD2) or R32G32_FLOAT (OW2/default)
    // Read raw bytes; interpret based on what we find
    const auto* exp_raw16 = reinterpret_cast<const uint16_t*>(data + DIAG_EXPOSURE_OFFSET);
    const auto* exp_raw32 = reinterpret_cast<const float*>(data + DIAG_EXPOSURE_OFFSET);
    float exp_r16 = half_to_float(exp_raw16[0]);
    float exp_r32 = exp_raw32[0];

    // Dilated MV (R16G16_FLOAT at upscale-res center — what Pre shader produced)
    const auto* dmv = reinterpret_cast<const uint16_t*>(data + DIAG_DILATED_MV_OFFSET);
    float dmv_x = half_to_float(dmv[0]), dmv_y = half_to_float(dmv[1]);

    // RCAS temp (R16G16B16A16_FLOAT — pre-RCAS model output, before sharpening)
    const auto* rcas = reinterpret_cast<const uint16_t*>(data + DIAG_RCAS_TEMP_OFFSET);
    float rcas_r = half_to_float(rcas[0]), rcas_g = half_to_float(rcas[1]);
    float rcas_b = half_to_float(rcas[2]), rcas_a = half_to_float(rcas[3]);

    D3D12_RANGE no_write = { 0, 0 };
    diag_readback->Unmap(0, &no_write);

    logf("DIAG upscale_center(%u,%u): history=(%.4f,%.4f,%.4f,%.4f) reproj=(%.4f,%.4f,%.4f,%.4f) "
         "recurrent=(%.3f,%.3f,%.3f,%.3f)\n",
         diag_center_x, diag_center_y,
         hist_r, hist_g, hist_b, hist_a,
         repr_r, repr_g, repr_b, repr_a,
         rec_r, rec_g, rec_b, rec_a);

    logf("DIAG output_center: (%.4f,%.4f,%.4f,%.4f)\n",
         out_r, out_g, out_b, out_a);
    logf("DIAG rcas_temp_center: (%.4f,%.4f,%.4f,%.4f)\n",
         rcas_r, rcas_g, rcas_b, rcas_a);
    logf("DIAG input_color_center: (%.4f,%.4f,%.4f,%.4f)\n",
         inp_r, inp_g, inp_b, inp_a);
    logf("DIAG exposure: r16=%.6f r32=%.6f raw16=0x%04X\n",
         exp_r16, exp_r32, exp_raw16[0]);
    logf("DIAG dilated_mv_center: (%.8f,%.8f)\n", dmv_x, dmv_y);

    for (auto& s : mv_samples) {
        logf("DIAG mv_%s: hex=(0x%04X,0x%04X) float=(%.8f,%.8f)\n",
             s.name, s.raw[0], s.raw[1], s.val[0], s.val[1]);
    }
}
#endif  // !FSR4_RELEASE

// =========================================================================
// Create / Destroy
// =========================================================================

bool FSR4D3D12Pipeline::create(
    ID3D12Device* device,
    uint32_t render_w, uint32_t render_h,
    uint32_t upscale_w, uint32_t upscale_h,
    uint32_t create_flags)
{
    // Align upscale size to 8 (matches AMD)
    this->max_upscale_w = align_up(upscale_w, 8u);
    this->max_upscale_h = align_up(upscale_h, 8u);
    this->max_render_w = render_w;
    this->max_render_h = render_h;

    // Select resolution tier based on upscale dimensions
    if (max_upscale_w > 3840 || max_upscale_h > 2160)
        resolution_tier = 2;  // 4320p
    else if (max_upscale_w > 1920 || max_upscale_h > 1080)
        resolution_tier = 1;  // 2160p
    else
        resolution_tier = 0;  // 1080p

    const char* preset_labels[] = { "quality", "balanced", "performance", "ultraperf" };
    logf("Creating D3D12 pipeline: render=%ux%u, upscale=%ux%u, tier=%dp, preset=%s\n",
         render_w, render_h, max_upscale_w, max_upscale_h,
         resolution_tier == 0 ? 1080 : resolution_tier == 1 ? 2160 : 4320,
         preset_labels[quality_preset]);

    if (!create_root_signatures(device)) return false;
    if (!create_psos(device)) return false;
    if (!create_descriptor_heap(device)) return false;
    if (!create_internal_resources(device)) return false;

    setup_internal_descriptors(device);
    resources_created = true;

    logf("D3D12 pipeline created successfully (%d PSOs)\n", PSO_COUNT);
    return true;
}

void FSR4D3D12Pipeline::destroy() {
    // PSOs
    for (auto& p : pso) {
        if (p) { p->Release(); p = nullptr; }
    }
    if (pso_post_normal) { pso_post_normal->Release(); pso_post_normal = nullptr; }

    // Root signatures
    if (pre_post_root_sig) { pre_post_root_sig->Release(); pre_post_root_sig = nullptr; }
    if (model_root_sig) { model_root_sig->Release(); model_root_sig = nullptr; }

    // Textures
    for (auto& t : textures) {
        if (t) { t->Release(); t = nullptr; }
    }

    // Buffers
    if (scratch_buffer) { scratch_buffer->Release(); scratch_buffer = nullptr; }
    if (initializer_buffer) { initializer_buffer->Release(); initializer_buffer = nullptr; }
    if (initializer_upload) { initializer_upload->Release(); initializer_upload = nullptr; }

    // Upload buffers
    if (cb_upload) {
        if (cb_mapped) { cb_upload->Unmap(0, nullptr); cb_mapped = nullptr; }
        cb_upload->Release(); cb_upload = nullptr;
    }

    // Descriptor heap
    if (srv_uav_heap) { srv_uav_heap->Release(); srv_uav_heap = nullptr; }

#ifndef FSR4_RELEASE
    // Diagnostic readback
    if (diag_readback) { diag_readback->Release(); diag_readback = nullptr; }
    // Timestamp profiling
    if (timestamp_heap) { timestamp_heap->Release(); timestamp_heap = nullptr; }
    if (timestamp_readback) { timestamp_readback->Release(); timestamp_readback = nullptr; }
#endif

    resources_created = false;
    initializer_uploaded = false;
    logf("D3D12 pipeline destroyed\n");
}

